import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.C9sp7nFj.js";const h=JSON.parse('{"title":"DAPOS","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/2. 位置数据类型/DAPOS.md","filePath":"2. 变量数据类型/2. 位置数据类型/DAPOS.md","lastUpdated":1778862643000}'),o={name:"2. 变量数据类型/2. 位置数据类型/DAPOS.md"};function l(s,t,c,n,i,_){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="dapos" tabindex="-1">DAPOS <a class="header-anchor" href="#dapos" aria-label="Permalink to &quot;DAPOS&quot;">​</a></h1><p>关节相对位置类型</p><p>存储关节空间下各个轴的相对偏移量。该变量可支持用户自主创建以及修改，也可在示教程序中进行赋值运算等操作。同时该变量支持在全局，工程，程序三大变量作用域中创建，删除，修改，复制，粘贴等操作（其中复制、粘贴操作不能跨域和跨工程）。</p><ul><li><strong>含义：</strong> 存储关节空间中各轴的<strong>相对偏移量</strong>。</li><li><strong>构成：</strong> <code>da1</code> 到 <code>da16</code>。</li><li><strong>场景：</strong> 常用于在当前关节位置基础上，让某个轴单独旋转一个特定的增量。</li></ul><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>da1</code></td><td>real</td><td>关节 1 号轴角度的偏移量。</td><td>—</td></tr><tr><td><code>da2</code></td><td>real</td><td>关节 2 号轴角度的偏移量。</td><td>—</td></tr><tr><td><code>da3</code></td><td>real</td><td>关节 3 号轴角度的偏移量。</td><td>—</td></tr><tr><td><code>da16</code></td><td>real</td><td>关节 16 号轴角度的偏移量。</td><td>机器人有几个轴就会显示几个轴的参数。如六轴机器人显示 da1~da6，scara 机器人显示为 da1~da4。</td></tr></tbody></table><ul><li>...：参数 da4~da15 的属性跟上述一样，都是 real 型变量，依次表示关节 4~关节 15 号轴角度的偏移量。</li></ul>',6)])])}const P=d(o,[["render",l]]);export{h as __pageData,P as default};
